use mrml_crypto::Sha256;
use mrml_runtime::{Text,Vector};
use crate::{BinaryReader,BinaryWriter,ProtocolError,RsaPrivateKey,RsaPublicKey,encode_rsa_public_key,sign_rsa_sha2_256,verify_rsa_sha2_256};
use crate::keyfile::{base64_decode,base64_encode};
const MAGIC:&[u8]=b"SSHSIG";

pub fn sign_sshsig(key:&RsaPrivateKey,namespace:&str,message:&[u8])->Result<Text,ProtocolError>{validate_namespace(namespace)?;let public=encode_rsa_public_key(&key.public)?;let signed=signed_data(namespace,message)?;let signature=sign_rsa_sha2_256(key,&signed)?;let mut envelope=Vector::new();envelope.extend(MAGIC.iter().copied());let mut fields=BinaryWriter::new();fields.string(&public)?;fields.string(namespace.as_bytes())?;fields.string(&[])?;fields.string(b"sha256")?;fields.string(&signature)?;envelope.extend(fields.finish());let encoded=base64_encode(&envelope);let mut armor=Text::from("-----BEGIN SSH SIGNATURE-----\n");for chunk in encoded.as_bytes().chunks(70){armor.push_str(core::str::from_utf8(chunk).map_err(|_|ProtocolError::InvalidUtf8)?);armor.push('\n');}armor.push_str("-----END SSH SIGNATURE-----\n");Ok(armor)}

pub fn verify_sshsig(expected:&RsaPublicKey,namespace:&str,message:&[u8],armor:&str)->Result<(),ProtocolError>{validate_namespace(namespace)?;let body=armor.trim().strip_prefix("-----BEGIN SSH SIGNATURE-----").and_then(|value|value.strip_suffix("-----END SSH SIGNATURE-----")).ok_or(ProtocolError::Authentication)?;let envelope=base64_decode(body)?;if !envelope.starts_with(MAGIC){return Err(ProtocolError::Authentication);}let mut reader=BinaryReader::new(&envelope[MAGIC.len()..]);let public=reader.string()?;if public!=&*encode_rsa_public_key(expected)?||reader.text()?!=namespace||!reader.string()?.is_empty()||reader.text()? != "sha256"{return Err(ProtocolError::Authentication);}let signature=reader.string()?;if reader.remaining()!=0{return Err(ProtocolError::Authentication);}verify_rsa_sha2_256(public,&signed_data(namespace,message)?,signature)}
fn signed_data(namespace:&str,message:&[u8])->Result<Vector<u8>,ProtocolError>{let mut output=Vector::new();output.extend(MAGIC.iter().copied());let mut fields=BinaryWriter::new();fields.string(namespace.as_bytes())?;fields.string(&[])?;fields.string(b"sha256")?;fields.string(&Sha256::digest(message))?;output.extend(fields.finish());Ok(output)}
fn validate_namespace(value:&str)->Result<(),ProtocolError>{if value.is_empty()||value.len()>255||value.bytes().any(|b|b<=0x20||b>=0x7f){Err(ProtocolError::InvalidUtf8)}else{Ok(())}}

#[cfg(test)]mod tests{use super::*;
 fn decode(text:&str)->Vector<u8>{(0..text.len()/2).map(|i|u8::from_str_radix(&text[i*2..i*2+2],16).unwrap()).collect()}
 fn key()->RsaPrivateKey{RsaPrivateKey{public:RsaPublicKey{modulus:decode("9eff1e540991fee9de7c7ed50d5da16508d610090a52c9aa4c41bc868e93e7cc03a6cc766fb2dab78ba91e4315f6524e355fda2c8a71b372f012d43460c2c425c2ae763d96a20584bc030e3595cc9f2352f51288f8db5d398d55efc566381707b4df848444641093fc5c48ca894db8397b252d00d5d606fe377b09f3609850fb"),exponent:Vector::from([1,0,1])},private_exponent:decode("2187d1e08d2821e736497102035094a1d70c35d3823ed552b9c43f3aed4499e4b77c6cb0297c418de5c123a5a8330b467d111ad4bbd9a0ab839fa4eaeae108364d4ad3f439916be8a244f8071922b1918cce92b27fe5f6ed24a328b15030b3fb3e300166c651f5f457daef746c4051a7a0f035379dcacf3a164fb4aedd284a11")}}
 #[test]fn git_namespace_signature_round_trips_and_binds_message(){let key=key();let armor=sign_sshsig(&key,"git",b"commit bytes").unwrap();assert!(armor.starts_with("-----BEGIN SSH SIGNATURE-----"));assert_eq!(verify_sshsig(&key.public,"git",b"commit bytes",&armor),Ok(()));assert_eq!(verify_sshsig(&key.public,"git",b"other",&armor),Err(ProtocolError::Authentication));assert_eq!(verify_sshsig(&key.public,"file",b"commit bytes",&armor),Err(ProtocolError::Authentication));}
}
